namespace hanmo::resident {
Integer social_trust(const SocialState& s,const StableId& from,const StableId& to){for(auto& row:s.relations.rows())if(row.second.from_actor==from&&row.second.to_actor==to)return row.second.trust;return 0;}
// social_change_relation and the selected source wrapper share the sole
// original clamp in social_relation_execution.cpp.
namespace {
// 人物的动态原型只查目录配置；永久动态授权由领域seed/profile gate先证明。
const SocialPolicy* policy_for(const CommonStore& c,const SocialCatalog& catalog,const StableId& id){return lookup_original_social_policy(c,catalog,id).policy;}
void remember(SocialState& s,const StableId& actor,const StableId& fact,Integer tick,const StableId& source){if(!s.memories.find(actor))s.memories.insert(actor,{});auto* m=s.memories.find(actor);if(!m->find(fact))m->insert(fact,{tick,source});}
const SocialMemory* memory(const SocialState& s,const StableId& actor,const StableId& fact){auto* m=s.memories.find(actor);return m?m->find(fact):nullptr;}
std::optional<SocialObservedFact> observed(const SocialState& s,const StableId& id,const SocialFactRead* other){if(auto* e=s.events.find(id)){if(e->kind=="news")return {};return SocialObservedFact{id,e->kind,e->actor_id,e->tick,{e->actor_id,e->target_actor_id}};}return other?other->social_fact(id):std::optional<SocialObservedFact>{};}
Outcome<StableId> event(CommonStore& c,SocialState& s,SocialEvent e,OriginalSocialCalendarRelationWrite* relations,const ExactPeriodContext* period,const WorldMoment* actual){auto id=c.next_id("social");if(!id.ok)return id;e.id=id.value;auto kind=e.kind,actor=e.actor_id,target=e.target_actor_id;auto tick=e.tick;s.events.insert(id.value,std::move(e));if(kind!="news"){remember(s,actor,id.value,tick,actor);remember(s,target,id.value,tick,target);}if(s.original_relation_version==2){if(!relations||!period||!actual||!relations->bound_to(c,s))return {false,{},common_failure("OriginalSocialCalendarRelationWriterRequired",{},ErrorKind::unsupported_capability).error};auto applied=relations->apply_original_calendar_event(id.value,*period,*actual);if(!applied.ok)return {false,{},applied.error};}return id;}
bool available(const CommonStore& c,const ActivityRead& activity,const StableId& id){auto* a=c.state().actors.find(id);if(!a||id==c.state().metadata.player_actor_id||!a->alive||!a->available||!a->action_id.empty()||a->injury>=3)return false;auto location=c.resolved_location(id);if(!location.ok||!std::holds_alternative<SettlementLocation>(location.value))return false;return !activity.in_open_battle(id)&&!activity.in_interaction(id);}
bool refusal_known(const SocialState& s,const StableId& helper,const StableId& requester,const StableId& item,const StableId& reason){auto* memories=s.memories.find(requester);if(!memories)return false;for(auto& row:memories->rows())if(auto* e=s.events.find(row.first))if(e->kind=="refusal"&&e->actor_id==helper&&e->target_actor_id==requester&&e->item_id==item&&e->reason==reason)return true;return false;}
Outcome<bool> transfer(CommonStore& c,const CommonCatalog& catalog,const StableId& from,const StableId& to,const StableId& item){auto* sender=c.actor(from);auto* receiver=c.actor(to);auto* dest=receiver?c.inventory(receiver->inventory_id):nullptr;auto* definition=catalog.items.find(item);if(!sender||!dest||!definition)return {false,false,common_failure("InvalidSocialParticipants").error};auto w=c.inventory_weight(dest->id);if(!w.ok)return {false,false,w.error};if(w.value+definition->weight>dest->capacity)return {true,false,{}};ResourceRecipe recipe;recipe.operations.push_back(TransferLots{sender->inventory_id,dest->id,item,1,{{Owner::Kind::actor,from,{}}},{},Owner{Owner::Kind::actor,to,{}}});auto result=c.apply_resources(recipe);if(!result.ok){if(result.error.kind!=ErrorKind::rule)return {false,false,result.error};return {true,false,{}};}return {true,true,{}};}
Status exchange(CommonStore& c,SocialState& s,const SocialCatalog& policies,const CommonCatalog& catalog,const StableId& actor,const StableId& target,const SocialPolicy& policy,Integer tick,const StableId& place,std::vector<StableId>& emitted,OriginalSocialCalendarRelationWrite* relations,const ExactPeriodContext* period,const WorldMoment* actual){auto a=c.count(c.actor(actor)->inventory_id,policy.food_item_id,{{Owner::Kind::actor,actor,{}}});auto b=c.count(c.actor(target)->inventory_id,policy.food_item_id,{{Owner::Kind::actor,target,{}}});if(!a.ok)return {false,{},a.error};if(!b.ok)return {false,{},b.error};
    auto emit=[&](const StableId& kind,const StableId& person,const StableId& other,Integer q,const StableId& reason)->Status{auto r=event(c,s,{{},kind,tick,place,person,other,policy.food_item_id,q,reason,{}},relations,period,actual);if(!r.ok)return {false,{},r.error};emitted.push_back(r.value);return common_success();};
    if(policy.kind=="selfish"){if(a.value==0&&b.value>0){auto moved=transfer(c,catalog,target,actor,policy.food_item_id);if(!moved.ok)return {false,{},moved.error};if(moved.value){if(s.original_relation_version==2)return emit("theft",actor,target,1,"shortage");auto r=change_original_social_relation_legacy(c,s,target,actor,OriginalSocialRelationRule::theft_victim);if(!r.ok)return r;r=change_original_social_relation_legacy(c,s,actor,target,OriginalSocialRelationRule::theft_actor);if(!r.ok)return r;return emit("theft",actor,target,1,"shortage");}}return common_success();}
    StableId helper,requester;if(a.value>=2&&b.value==0){helper=actor;requester=target;}else if(a.value==0&&b.value>=2){helper=target;requester=actor;}if(helper.empty())return common_success();auto* hp=policy_for(c,policies,helper);bool selfish=hp&&hp->kind=="selfish";
    if(selfish||social_trust(s,helper,requester)<20){StableId reason=selfish?"selfish":"distrust";if(!refusal_known(s,helper,requester,policy.food_item_id,reason)){if(s.original_relation_version==2)return emit("refusal",helper,requester,0,reason);auto r=change_original_social_relation_legacy(c,s,requester,helper,OriginalSocialRelationRule::refusal);if(!r.ok)return r;return emit("refusal",helper,requester,0,reason);}}
    else {auto moved=transfer(c,catalog,helper,requester,policy.food_item_id);if(!moved.ok)return {false,{},moved.error};if(moved.value){if(s.original_relation_version==2)return emit("aid",helper,requester,1,"shortage");auto r=change_original_social_relation_legacy(c,s,requester,helper,OriginalSocialRelationRule::aid_receiver);if(!r.ok)return r;r=change_original_social_relation_legacy(c,s,helper,requester,OriginalSocialRelationRule::aid_helper);if(!r.ok)return r;return emit("aid",helper,requester,1,"shortage");}}return common_success();}
// 原分享按源事实ID字典序，只取一步初已知且接收者尚未知的一条。
Status share(CommonStore& c,SocialState& s,const OrderedTable<OrderedTable<SocialMemory>>& start,const StableId& sender,const StableId& receiver,Integer tick,const StableId& place,std::vector<StableId>& emitted,OriginalSocialCalendarRelationWrite* relations=nullptr,const ExactPeriodContext* period=nullptr,const WorldMoment* actual=nullptr){auto* memories=start.find(sender);if(!memories)return common_success();auto ids=memories->order();std::sort(ids.begin(),ids.end());for(auto& id:ids){if(memories->find(id)->learned_tick>=tick||memory(s,receiver,id))continue;remember(s,receiver,id,tick,sender);if(s.original_relation_version==1)if(auto* f=s.events.find(id)){Status changed=common_success();if(f->kind=="theft"&&receiver!=f->actor_id)changed=change_original_social_relation_legacy(c,s,receiver,f->actor_id,OriginalSocialRelationRule::heard_theft);else if(f->kind=="aid"&&receiver!=f->actor_id)changed=change_original_social_relation_legacy(c,s,receiver,f->actor_id,OriginalSocialRelationRule::heard_aid);if(!changed.ok)return changed;}auto e=event(c,s,{{},"news",tick,place,sender,receiver,{},0,{},id},relations,period,actual);if(!e.ok)return {false,{},e.error};emitted.push_back(e.value);break;}return common_success();}
}
static Status validate_social_original_at(const CommonStore& c,const SocialState& s,const CommonCatalog& catalog,const SocialFactRead* other,std::optional<Integer> unselected_clock_origin,bool exact_supply_source_scope,Integer processed_tick){
    // 新窄源组合仅由已核WorldBundle传入；旧Social宏观状态仍全空，dynamic另由完整typed期间闭包验证。
    if(exact_supply_source_scope&&(!unselected_clock_origin||!s.dynamic||!social_regional_time2_version(s.dynamic->version)||!s.dynamic->time2))return common_failure("ExactSocialClockScopeMismatch");
    // 原时标保安装点；未选分支保持原全空门，不能冒写已处理到当前。
    if(unselected_clock_origin){if(*unselected_clock_origin<0||*unselected_clock_origin>c.tick()||s.last_tick!=*unselected_clock_origin||!s.relations.empty()||!s.memories.empty()||!s.events.empty()||(!exact_supply_source_scope&&s.dynamic&&(!s.dynamic->reports.empty()||!s.dynamic->pending_messages.empty()||!s.dynamic->known_reports.empty())))return common_failure("UnselectedSocialClockHasBusiness");}
    if(s.last_tick<0||(!unselected_clock_origin&&s.last_tick!=processed_tick))return common_failure("InvalidSocialTick");
    for(auto& row:s.relations.rows()){auto& r=row.second;if(!c.actor(r.from_actor)||!c.actor(r.to_actor)||r.trust<0||r.trust>100||r.affinity<0||r.affinity>100)return common_failure("InvalidRelation",row.first);}
    for(auto& row:s.events.rows()){auto& e=row.second;auto suffix=e.id.substr(e.id.find(':')+1);Integer n=0;try{n=std::stoll(suffix);}catch(...){return common_failure("InvalidSocialEvent",row.first);}if(e.id!=row.first||e.id!="social:"+std::to_string(n)||n<1||n>=c.state().next_instance_id||e.tick<1||e.tick>s.last_tick||(e.kind!="aid"&&e.kind!="theft"&&e.kind!="refusal"&&e.kind!="news"))return common_failure("InvalidSocialEvent",row.first);if(!catalog.places.find(e.place_id)||e.actor_id==e.target_actor_id||!c.actor(e.actor_id)||!c.actor(e.target_actor_id))return common_failure("InvalidSocialParticipants",row.first);if(e.kind=="news"){if(!e.item_id.empty()||e.quantity!=0||!e.reason.empty()||!observed(s,e.fact_id,other))return common_failure("InvalidSocialNews",row.first);}else if(!catalog.items.find(e.item_id)||!e.fact_id.empty()||e.quantity!=(e.kind=="refusal"?0:1)||(e.kind=="refusal"?(e.reason!="distrust"&&e.reason!="selfish"):e.reason!="shortage"))return common_failure("InvalidSocialTransfer",row.first);}
    for(auto& row:s.memories.rows()){if(!c.actor(row.first))return common_failure("InvalidSocialMemory",row.first);for(auto& item:row.second.rows()){auto& m=item.second;auto f=observed(s,item.first,other);if(!f||!c.actor(m.source_actor_id)||m.learned_tick<0||m.learned_tick>s.last_tick)return common_failure("InvalidSocialMemory",item.first);if(f->tick<0||f->tick>m.learned_tick)return common_failure("InvalidSocialMemoryTime",item.first);if(m.source_actor_id==row.first){if(std::find(f->participants.begin(),f->participants.end(),row.first)==f->participants.end())return common_failure("InvalidSocialWitness",item.first);}else{auto* source=memory(s,m.source_actor_id,item.first);bool transmission=false;for(auto& er:s.events.rows()){auto& e=er.second;if(e.kind=="news"&&e.fact_id==item.first&&e.actor_id==m.source_actor_id&&e.target_actor_id==row.first&&e.tick==m.learned_tick){transmission=true;break;}}if(!source||source->learned_tick>=m.learned_tick||!transmission)return common_failure("InvalidSocialProvenance",item.first);}}}
    for(auto& row:s.events.rows()){auto& e=row.second;if(e.kind=="news"){auto* m=memory(s,e.target_actor_id,e.fact_id);if(!m||m->source_actor_id!=e.actor_id||m->learned_tick!=e.tick)return common_failure("InvalidSocialNews",row.first);}else for(auto& participant:{e.actor_id,e.target_actor_id}){auto* m=memory(s,participant,e.id);if(!m||m->learned_tick!=e.tick||m->source_actor_id!=participant)return common_failure("InvalidSocialWitness",row.first);}}
    return common_success();
}
Status validate_social(const CommonStore&c,const SocialState&s,const CommonCatalog&catalog,const SocialFactRead*other,std::optional<Integer>origin,bool exact_scope){return validate_social_original_at(c,s,catalog,other,origin,exact_scope,c.tick());}
Status validate_social_at_moment(const CommonStore&c,const SocialState&s,const CommonCatalog&catalog,const SocialFactRead*other,const WorldMoment&actual){auto shape=compare_world_moments(actual,actual);if(!shape.ok)return {false,{},shape.error};return validate_social_original_at(c,s,catalog,other,{},false,actual.half_day_tick);}
static Outcome<SocialEffects> step_social_original(CommonStore&c,SocialState&s,const SocialCatalog&catalog,const CommonCatalog&common,const ActivityRead&activity,Integer finish,const SocialFactRead*other,const SocialCalendarDispatchRead*routes,OriginalSocialCalendarRelationWrite* relations=nullptr,const ExactPeriodContext* period=nullptr,const WorldMoment* actual=nullptr){SocialEffects result;const auto& memories=s.memories;
    auto facts=c.state().facts.order();std::sort(facts.begin(),facts.end());for(auto& id:facts){auto* h=c.state().facts.find(id);if(!other&&(h->kind=="personal_battle"||h->kind=="training"||h->kind=="aid"||h->kind=="theft"||h->kind=="refusal"))return {false,{},common_failure("SocialFactProjectionRequired",id,ErrorKind::unsupported_capability).error};if(other){auto f=other->social_fact(id);if(f&&f->tick>=0&&f->tick<=finish)for(auto& person:f->participants)if(c.actor(person))remember(s,person,id,finish,person);}}
    auto ids=c.actor_order();std::sort(ids.begin(),ids.end());std::set<StableId> occupied;for(auto& id:ids){auto* policy=policy_for(c,catalog,id);if(!policy)continue;if(policy->interval_ticks<=0)return {false,{},common_failure("InvalidSocialPolicy",id).error};if(finish%policy->interval_ticks)continue;auto target=policy->target_actor_id;if(occupied.count(id)||occupied.count(target)||id==target||!available(c,activity,id)||!available(c,activity,target))continue;auto x=c.resolved_location(id),y=c.resolved_location(target);auto& a=std::get<SettlementLocation>(x.value);auto& b=std::get<SettlementLocation>(y.value);if(a.place_id!=b.place_id||a.settlement_id!=b.settlement_id)continue;SocialCalendarDispatch actor_route,target_route;if(routes){auto route=routes->dispatch(id);if(!route.ok)return {false,{},route.error};actor_route=route.value;route=routes->dispatch(target);if(!route.ok)return {false,{},route.error};target_route=route.value;}auto before=result.events.size();Status r=common_success();if(actor_route.exchange){r=exchange(c,s,catalog,common,id,target,*policy,finish,a.place_id,result.events,relations,period,actual);if(!r.ok)return {false,{},r.error};}if(actor_route.share_news&&policy->share_news){r=share(c,s,memories,id,target,finish,a.place_id,result.events,relations,period,actual);if(!r.ok)return {false,{},r.error};}auto* target_policy=policy_for(c,catalog,target);if(target_route.share_news&&target_policy&&target_policy->share_news){r=share(c,s,memories,target,id,finish,a.place_id,result.events,relations,period,actual);if(!r.ok)return {false,{},r.error};}if(result.events.size()>before){occupied.insert(id);occupied.insert(target);}}
    s.last_tick=finish;result.applied=true;return {true,std::move(result),{}};
}
Outcome<SocialEffects> step_social(CommonStore&c,SocialState&s,const SocialCatalog&catalog,const CommonCatalog&common,const ActivityRead&activity,Integer finish,const SocialFactRead*other){if(s.original_relation_version!=1)return {false,{},common_failure("OriginalSocialCalendarSourceRequired",{},ErrorKind::unsupported_capability).error};auto valid=validate_social(c,s,common,other);if(!valid.ok)return {false,{},valid.error};if(finish==s.last_tick)return {true,{}, {}};if(c.tick()==std::numeric_limits<Integer>::max()||finish!=c.tick()+1||s.last_tick!=c.tick())return {false,{},common_failure("SocialTickMismatch").error};return step_social_original(c,s,catalog,common,activity,finish,other,nullptr);}
Outcome<SocialEffects> step_social_at_period(CommonStore&c,SocialState&s,const SocialCatalog&catalog,const CommonCatalog&common,const ActivityRead&activity,const SocialFactRead*other,const ExactPeriodContext&period,const WorldMoment&actual,const SocialCalendarDispatchRead*routes,OriginalSocialCalendarRelationWrite* relations){if(s.original_relation_version==2){if(!relations||!relations->bound_to(c,s))return {false,{},common_failure("OriginalSocialCalendarRelationWriterRequired",{},ErrorKind::unsupported_capability).error};auto ready=relations->validate_period_candidate(period,actual);if(!ready.ok)return {false,{},ready.error};}else if(s.original_relation_version!=1)return {false,{},common_failure("UnsupportedOriginalSocialVersion",{},ErrorKind::unsupported_capability).error};auto whole=compare_fractions(period.opening_at.sub_half_day,CanonicalFraction{});if(!whole.ok)return {false,{},whole.error};auto end=compare_world_moments(actual,{period.through_tick,{}});if(!end.ok)return {false,{},end.error};if(whole.value||end.value||period.period_id.empty()||period.opening_at.half_day_tick==std::numeric_limits<Integer>::max()||period.through_tick!=period.opening_at.half_day_tick+1)return {false,{},common_failure("SocialOriginalPeriodMismatch",period.period_id).error};if(s.last_tick==period.through_tick){auto valid=validate_social_at_moment(c,s,common,other,actual);return valid.ok?Outcome<SocialEffects>{true,{}, {}}:Outcome<SocialEffects>{false,{},valid.error};}auto valid=validate_social_original_at(c,s,common,other,{},false,period.opening_at.half_day_tick);if(!valid.ok)return {false,{},valid.error};return step_social_original(c,s,catalog,common,activity,period.through_tick,other,routes,relations,&period,&actual);}
Outcome<SocialEffects> hear_social_news(CommonStore& c,SocialState& s,const CommonCatalog& catalog,const StableId& listener,const StableId& speaker,Integer tick,const SocialFactRead* other){if(s.original_relation_version!=1)return {false,{},common_failure("OriginalSocialNewsActualSourceRequired",{},ErrorKind::unsupported_capability).error};if(listener==speaker||!c.actor(listener)||!c.actor(speaker))return {false,{},common_failure("InvalidSocialParticipants").error};auto valid=validate_social(c,s,catalog,other);if(!valid.ok)return {false,{},valid.error};if(tick!=c.tick())return {false,{},common_failure("SocialTickMismatch").error};auto loc=c.resolved_location(speaker);StableId place;if(loc.ok)if(auto* p=std::get_if<SettlementLocation>(&loc.value))place=p->place_id;SocialEffects result;const auto& memories=s.memories;auto r=share(c,s,memories,speaker,listener,tick,place,result.events);if(!r.ok)return {false,{},r.error};return {true,std::move(result),{}};}
} // 内部/能力失败由外层事务整体回滚；原普通转交失败只停止本次交流。
